// Minimal CPython 3.12 marshal parser (no pyc header — raw marshal payload)
export function parseMarshal(buf) {
  let pos = 0;
  const refs = [];
  function readByte() { return buf[pos++]; }
  function readLong() {
    const v = buf.readInt32LE(pos); pos += 4; return v;
  }
  function readObj() {
    let t = readByte();
    const flagRef = t & 0x80;
    t = String.fromCharCode(t & 0x7f);
    let val;
    switch (t) {
      case 'N': val = null; break;
      case 'F': val = false; break;
      case 'T': val = true; break;
      case '.': val = { __stop: true }; break;
      case '0': val = { __null: true }; break;
      case 'i': val = readLong(); break;
      case 'I': { const v = buf.readBigInt64LE(pos); pos += 8; val = Number(v); break; }
      case 'g': { const v = buf.readDoubleLE(pos); pos += 8; val = v; break; }
      case 'l': {
        let n = readLong(); const neg = n < 0; n = Math.abs(n);
        let v = 0n;
        for (let i = 0; i < n; i++) { const d = buf.readUInt16LE(pos); pos += 2; v |= BigInt(d) << BigInt(15 * i); }
        val = neg ? -v : v; break;
      }
      case 's': { const n = readLong(); val = { __bytes: buf.subarray(pos, pos + n) }; pos += n; break; }
      case 'u': case 'a': case 'A': { const n = readLong(); val = buf.subarray(pos, pos + n).toString('utf8'); pos += n; break; }
      case 't': case 'z': case 'Z': { const n = t === 't' ? readLong() : readByte(); val = buf.subarray(pos, pos + n).toString('utf8'); pos += n; break; }
      case ')': { const n = readByte(); val = []; for (let i = 0; i < n; i++) val.push(readObj()); break; }
      case '(': { const n = readLong(); val = []; for (let i = 0; i < n; i++) val.push(readObj()); break; }
      case '[': { const n = readLong(); val = []; for (let i = 0; i < n; i++) val.push(readObj()); break; }
      case '>': { const n = readLong(); val = { __frozenset: [] }; for (let i = 0; i < n; i++) val.__frozenset.push(readObj()); break; }
      case '<': { const n = readLong(); val = { __set: [] }; for (let i = 0; i < n; i++) val.__set.push(readObj()); break; }
      case '{': { val = { __dict: [] }; for (;;) { const k = readObj(); if (k === null) break; val.__dict.push([k, readObj()]); } break; }
      case 'r': { const idx = readLong(); return refs[idx]; }
      case 'c': {
        const co = { __code: true };
        co.argcount = readLong();
        co.posonly = readLong();
        co.kwonly = readLong();
        co.stacksize = readLong();
        co.flags = readLong();
        co.code = readObj();
        co.consts = readObj();
        co.names = readObj();
        co.varnames = readObj();
        co.freevars = readObj();
        co.cellvars = readObj();
        co.filename = readObj();
        co.name = readObj();
        co.qualname = readObj();
        co.firstlineno = readLong();
        co.linetable = readObj();
        co.exceptiontable = readObj();
        val = co;
        break;
      }
      default:
        throw new Error(`unknown marshal type '${t}' (0x${t.charCodeAt(0).toString(16)}) at ${pos - 1}`);
    }
    if (flagRef) refs.push(val);
    return val;
  }
  return readObj();
}

// Python 3.12 opmap (from dis). Generated subset covering full 3.12 table.
export const opname3_12 = (() => {
  const op = [];
  const def = (n, code) => { op[code] = n; };
  def('CACHE', 0); def('POP_TOP', 1); def('PUSH_NULL', 2); def('NOP', 9);
  def('UNARY_POSITIVE', 10); def('UNARY_NEGATIVE', 11); def('UNARY_NOT', 12);
  def('UNARY_INVERT', 15); def('BINARY_SUBSCR', 25); def('GET_LEN', 30);
  def('MATCH_MAPPING', 31); def('MATCH_SEQUENCE', 32); def('MATCH_KEYS', 33);
  def('PUSH_EXC_INFO', 35); def('CHECK_EXC_MATCH', 36); def('CHECK_EG_MATCH', 37);
  def('WITH_EXCEPT_START', 49); def('GET_AITER', 50); def('GET_ANEXT', 51);
  def('BEFORE_ASYNC_WITH', 52); def('END_FOR', 54); def('INPLACE_ADD', 55);
  def('INPLACE_SUBTRACT', 56); def('INPLACE_MULTIPLY', 57); def('INPLACE_MODULO', 59);
  def('STORE_SUBSCR', 60); def('DELETE_SUBSCR', 61); def('BINARY_LSHIFT', 62);
  def('BINARY_RSHIFT', 63); def('BINARY_AND', 64); def('BINARY_XOR', 65);
  def('BINARY_OR', 66); def('INPLACE_POWER', 67); def('GET_ITER', 68);
  def('GET_YIELD_FROM_ITER', 69); def('PRINT_EXPR', 70); def('LOAD_BUILD_CLASS', 71);
  def('LOAD_ASSERTION_ERROR', 74); def('INPLACE_LSHIFT', 75); def('INPLACE_RSHIFT', 76);
  def('INPLACE_AND', 77); def('INPLACE_XOR', 78); def('INPLACE_OR', 79);
  def('LIST_TO_TUPLE', 82); def('RETURN_VALUE', 83); def('IMPORT_STAR', 84);
  def('SETUP_ANNOTATIONS', 85); def('YIELD_VALUE', 86); def('POP_BLOCK', 87);
  def('POP_EXCEPT', 89); def('STORE_NAME', 90); def('DELETE_NAME', 91);
  def('UNPACK_SEQUENCE', 92); def('FOR_ITER', 93); def('UNPACK_EX', 94);
  def('STORE_ATTR', 95); def('DELETE_ATTR', 96); def('STORE_GLOBAL', 97);
  def('DELETE_GLOBAL', 98); def('SWAP', 99); def('LOAD_CONST', 100);
  def('LOAD_NAME', 101); def('BUILD_TUPLE', 102); def('BUILD_LIST', 103);
  def('BUILD_SET', 104); def('BUILD_MAP', 105); def('LOAD_ATTR', 106);
  def('COMPARE_OP', 107); def('IMPORT_NAME', 108); def('IMPORT_FROM', 109);
  def('JUMP_FORWARD', 110); def('JUMP_IF_FALSE_OR_POP', 111); def('JUMP_IF_TRUE_OR_POP', 112);
  def('POP_JUMP_IF_FALSE', 114); def('POP_JUMP_IF_TRUE', 115); def('LOAD_GLOBAL', 116);
  def('IS_OP', 117); def('CONTAINS_OP', 118); def('RERAISE', 119);
  def('COPY', 120); def('BINARY_OP', 122); def('SEND', 123);
  def('LOAD_FAST', 124); def('STORE_FAST', 125); def('DELETE_FAST', 126);
  def('POP_JUMP_IF_NOT_NONE', 128); def('POP_JUMP_IF_NONE', 129);
  def('LOAD_SUPER_ATTR', 141); def('LOAD_FAST_CHECK', 127);
  def('BUILD_SLICE', 133); def('JUMP_BACKWARD_NO_INTERRUPT', 134);
  def('MAKE_CELL', 135); def('LOAD_CLOSURE', 136); def('LOAD_DEREF', 137);
  def('STORE_DEREF', 138); def('DELETE_DEREF', 139); def('JUMP_BACKWARD', 140);
  def('CALL_FUNCTION_EX', 142); def('EXTENDED_ARG', 144); def('LIST_APPEND', 145);
  def('SET_ADD', 146); def('MAP_ADD', 147); def('LOAD_CLASSDEREF', 148);
  def('COPY_FREE_VARS', 149); def('RESUME', 151); def('MATCH_CLASS', 152);
  def('FORMAT_VALUE', 155); def('BUILD_CONST_KEY_MAP', 156); def('BUILD_STRING', 157);
  def('LOAD_METHOD', 160); def('LIST_EXTEND', 162); def('SET_UPDATE', 163);
  def('DICT_MERGE', 164); def('DICT_UPDATE', 165); def('CALL', 171);
  def('KW_NAMES', 172); def('PRECALL', 166); def('BINARY_OP_ADAPTIVE', 3);
  def('RETURN_GENERATOR', 75); def('MAKE_FUNCTION', 132); def('GET_AWAITABLE', 73);
  def('SETUP_WITH', 143); def('BEFORE_WITH', 53);
  return op;
})();

const HAVE_ARG = 90; // not exact for 3.12; we treat all with arg below
const hasarg = new Set();
// In 3.12, HAVE_ARGUMENT = 43? Actually dis.HAVE_ARGUMENT = 43 for 3.12? It's 90 historically; 3.12 uses 43? 
// Simpler: opcodes without arg in 3.12: CACHE(0), POP_TOP(1), PUSH_NULL(2)... We'll encode explicitly:
const NOARG = new Set([0, 1, 9, 10, 11, 12, 15, 30, 31, 32, 33, 54, 55, 56, 57, 59, 60, 61, 62, 63, 64, 65, 66, 67, 68, 69, 70, 75, 76, 77, 78, 79, 82, 83, 84, 87, 89, 99, 119, 120, 151, 166, 85, 86, 135, 149, 52, 53, 35, 36, 37]);

const cmp_op = ['<', '<=', '==', '!=', '>', '>='];

export function disassemble(co, indent = '') {
  const code = co.code.__bytes;
  const names = co.names || [];
  const varnames = co.varnames || [];
  const consts = co.consts || [];
  const freevars = co.freevars || [];
  const cellvars = co.cellvars || [];
  const out = [];
  let ext = 0;
  const CACHE = 0;
  out.push(`${indent}== ${co.qualname || co.name} (args=${co.argcount},varnames=${JSON.stringify(varnames)})`);
  for (let i = 0; i < code.length; i += 2) {
    const opc = code[i];
    let arg = code[i + 1] | ext; ext = 0;
    if (opc === 144) { ext = (code[i + 1]) << 8; continue; }
    if (opc === CACHE) continue;
    const name = opname3_12[opc] || `OP${opc}`;
    let argval = '';
    if (!NOARG.has(opc)) {
      try {
        if (name.startsWith('LOAD_CONST')) argval = fmtConst(consts[arg]);
        else if (name.startsWith('LOAD_ATTR') || name.startsWith('LOAD_METHOD') || name.startsWith('LOAD_GLOBAL') || name.startsWith('IMPORT_NAME') || name.startsWith('LOAD_NAME') || name.startsWith('STORE_NAME') || name.startsWith('STORE_GLOBAL') || name.startsWith('STORE_ATTR') || name.startsWith('IMPORT_FROM') || name.startsWith('LOAD_SUPER_ATTR')) argval = String(names[arg >> (name.startsWith('LOAD_ATTR') || name.startsWith('LOAD_GLOBAL') || name.startsWith('LOAD_SUPER_ATTR') ? 1 : 0)] ?? names[arg]);
        else if (name.startsWith('LOAD_FAST') || name.startsWith('STORE_FAST') || name.startsWith('DELETE_FAST')) argval = String(varnames[arg]);
        else if (name.startsWith('LOAD_DEREF') || name.startsWith('STORE_DEREF') || name.startsWith('LOAD_CLOSURE') || name.startsWith('LOAD_CLASSDEREF')) argval = String((cellvars.concat(freevars))[arg]);
        else if (name === 'COMPARE_OP') argval = cmp_op[arg >> 4] ?? arg;
        else if (name.startsWith('JUMP') || name === 'FOR_ITER' || name === 'SEND' || name === 'POP_JUMP_IF_FALSE' || name === 'POP_JUMP_IF_TRUE' || name === 'POP_JUMP_IF_NONE' || name === 'POP_JUMP_IF_NOT_NONE') argval = '->' + (name.includes('BACKWARD') ? (i - arg * 2) : (i + 2 + arg * 2));
        else if (name === 'BINARY_OP' || name.startsWith('BINARY_OP') || name.startsWith('INPLACE')) argval = ['+', '-', '*', '*', '@', '/', '//', '%', '<<', '>>', '&', '^', '|', '**'][arg] ?? arg;
        else if (name === 'KW_NAMES') argval = String(consts[arg]);
      } catch (e) { argval = '?'; }
    }
    out.push(`${indent}${String(i).padStart(4)} ${name} ${NOARG.has(opc) ? '' : arg + (argval ? '  (' + argval + ')' : '')}`);
  }
  for (const c of consts) {
    if (c && c.__code) out.push(disassemble(c, indent + '  '));
  }
  return out.join('\n');
}

function fmtConst(c) {
  if (c === null) return 'None';
  if (c === true) return 'True';
  if (c === false) return 'False';
  if (typeof c === 'string') return JSON.stringify(c.length > 60 ? c.slice(0, 60) + '…' : c);
  if (c && c.__code) return '<code ' + c.name + '>';
  if (c && c.__bytes) return 'b[' + c.__bytes.length + ']';
  if (Array.isArray(c)) return '(' + c.map(fmtConst).join(',') + ')';
  if (c && c.__frozenset) return 'frozenset' + JSON.stringify(c.__frozenset);
  if (c && c.__set) return 'set' + JSON.stringify(c.__set);
  return String(c);
}

