let pos = 0, depth = 0;
const refs = [];
function rb(){return buf[pos++];}
function rl(){const v=buf.readInt32LE(pos);pos+=4;return v;}
let count = 0;
function r(path){
  if (count++ > 400) throw new Error('trace limit');
  const start = pos;
  let t = rb();
  const fr = t & 0x80; t = String.fromCharCode(t & 0x7f);
  let slot = -1; if (fr) { slot = refs.length; refs.push(0); }
  let extra='';
  switch(t){
    case 'N': case 'F': case 'T': break;
    case '0': break;
    case 'i': extra=rl(); break;
    case 's': {const n=rl(); extra='bytes['+n+']'; pos+=n; break;}
